// Continuous weapon systems and projectile interactions.
const MU_WEAPON_UPDATE_BASE=WeaponInstance.prototype.update;
WeaponInstance.prototype.update=function(dt){
 const r=MU_WEAPON_UPDATE_BASE.call(this,dt);
 if(this.id==="phase_wire"&&game.state==="PLAYING"){
  this.vsxWireTimer=(this.vsxWireTimer||0)-dt;this.vsxWirePath||=[];
  if(this.vsxWireTimer<=0){this.vsxWireTimer=.08;const p=game.player,last=this.vsxWirePath[this.vsxWirePath.length-1];if(!last||Math.hypot(p.x-last.x,p.y-last.y)>8)this.vsxWirePath.push({x:p.x,y:p.y,t:game.time});while(this.vsxWirePath.length>45)this.vsxWirePath.shift();if(this.vsxWirePath.length>18){const old=this.vsxWirePath.slice(0,-12).find(q=>Math.hypot(q.x-p.x,q.y-p.y)<34);if(old){const s=this.getStats(),pts=this.vsxWirePath.slice(this.vsxWirePath.indexOf(old)),cx=pts.reduce((a,q)=>a+q.x,0)/pts.length,cy=pts.reduce((a,q)=>a+q.y,0)/pts.length,rad=Math.min(s.area*1.45,Math.max(55,...pts.map(q=>Math.hypot(q.x-cx,q.y-cy))));for(const e of game.grid.queryCircle(cx,cy,rad+25)){if(!e.dead&&Math.hypot(e.x-cx,e.y-cy)<=rad+e.size)game.damageEnemy(e,s.damage*(this.special==="phaseCircuit"?1.35:1),{source:this,canCrit:true,knockback:35,fromX:cx,fromY:cy})}game.effects.push(new WaveEffect(cx,cy,rad,.4,0,0,this,"#65e8ff"));this.vsxWirePath=[]}}}
 }
 return r
};
const MU_RENDER_PERSIST_BASE=WeaponInstance.prototype.renderPersistent;
WeaponInstance.prototype.renderPersistent=function(g){MU_RENDER_PERSIST_BASE.call(this,g);if(this.id==="phase_wire"&&this.vsxWirePath?.length>1){g.save();g.strokeStyle="rgba(99,232,255,.65)";g.lineWidth=2;g.shadowBlur=8;g.shadowColor="#65e8ff";g.beginPath();g.moveTo(this.vsxWirePath[0].x,this.vsxWirePath[0].y);for(const q of this.vsxWirePath.slice(1))g.lineTo(q.x,q.y);g.stroke();g.restore()}};

const MU_PROJECTILE_UPDATE_BASE=Projectile.prototype.update;
Projectile.prototype.update=function(dt){const r=MU_PROJECTILE_UPDATE_BASE.call(this,dt);if(this.owner!=="player"||this.dead)return r;
 if(!this.vsxCoinRelayed){for(const c of game.vsxCoins||[]){if(!c.dead&&Math.hypot(this.x-c.x,this.y-c.y)<this.radius+c.radius+8){const t=game.findNearest(c.x,c.y,620);if(t){const n=normalize(t.x-c.x,t.y-c.y),sp=Math.max(280,Math.hypot(this.vx,this.vy));this.x=c.x;this.y=c.y;this.vx=n.x*sp;this.vy=n.y*sp;this.damage*=c.weapon.special==="trickChain"?1.42:1.28;this.vsxCoinRelayed=true;this.hit.clear();game.spark(c.x,c.y,"#ffd84d",5)}break}}}
 if(!this.vsxPrismRelayed){for(const p of game.vsxPrisms||[]){if(!p.dead&&Math.hypot(this.x-p.x,this.y-p.y)<this.radius+p.radius+6){const a=Math.atan2(this.vy,this.vx),sp=Math.max(260,Math.hypot(this.vx,this.vy)),base={x:p.x,y:p.y,radius:Math.max(2,this.radius*.82),damage:this.damage*.62,life:Math.min(1.6,this.life+.4),color:"#9feaff",weapon:this.weapon,pierce:Math.max(0,this.pierce-1),knockback:this.knockback*.7,vsxPrismRelayed:true};for(const d of [-.28,.28])game.projectiles.push(new Projectile({...base,vx:Math.cos(a+d)*sp,vy:Math.sin(a+d)*sp}));this.vsxPrismRelayed=true;game.spark(p.x,p.y,"#9feaff",8);break}}}
 if(game.worldEvent?.id==="bullet_bank"&&game.vsxBankedBullets?.length){for(const b of game.vsxBankedBullets){if(b.dead)continue;if(Math.hypot(this.x-b.x,this.y-b.y)<this.radius+7){b.dead=true;this.dead=true;game.spark(b.x,b.y,"#a7d9ff",5);break}}}
 return r};

const MU_DAMAGE_BASE=Game.prototype.damageEnemy;
Game.prototype.damageEnemy=function(e,a,o={}){if(!o.hourglassReplay){for(const m of this.vsxHourglassMines||[]){if(!m.dead&&Math.hypot(e.x-m.x,e.y-m.y)<=m.radius+e.size)m.register(e,a)}}if(VSX_ADMIN?.oneHit&&o?.source&&e&&!e.isCaptive)a=Math.max(a,e.hp+1);return MU_DAMAGE_BASE.call(this,e,a,o)};

// Puppet physics. Kept outside Enemy.update to avoid replacing boss AI.
function vsxUpdatePuppets(g,dt){for(const e of g.enemies){const p=e.vsxPuppet;if(!p)continue;if(e.dead||g.time>=p.until||e.isBoss||e.isMiniBoss){delete e.vsxPuppet;continue}const idx=p.slot||0,total=p.total||1,a=g.time*1.8+idx*Math.PI*2/total,r=95+idx*16,tx=g.player.x+Math.cos(a)*r,ty=g.player.y+Math.sin(a)*r,n=normalize(tx-e.x,ty-e.y);e.x+=n.x*150*dt*(1-(e.knockbackResistance||0));e.y+=n.y*150*dt*(1-(e.knockbackResistance||0));if((p.nextHit||0)<=g.time){p.nextHit=g.time+.5;for(const q of g.grid.queryCircle(e.x,e.y,e.size+30)){if(q===e||q.dead)continue;if(Math.hypot(q.x-e.x,q.y-e.y)<q.size+e.size+8)g.damageEnemy(q,p.weapon.getStats().damage*.55,{source:p.weapon,canCrit:false,knockback:45,fromX:e.x,fromY:e.y,silent:true})}}}}

// ---------- World event entities ----------
class VSX_EventMinimapProxy{
 constructor(target,type){this.target=target;this.type=type;this.x=target.x;this.y=target.y;this.dead=false}
 get used(){return !!this.target?.used}
 update(){if(!this.target||this.target.dead){this.dead=true;return}this.x=this.target.x;this.y=this.target.y}
 interact(){return this.target?.interact?.()}
 render(){}
}
window.VSX_EVENT_PROXY_SAFE=true;
function vsxMapEventObject(g,o,type){const p=new VSX_EventMinimapProxy(o,type);g.worldObjects.push(p);return o}
class VSX_EventBeacon{
 constructor(kind,x,y){this.kind=kind;this.x=x;this.y=y;this.dead=false;this.used=false;this.type=kind==="mountain"?"shrine":"trial_portal";this.life=60;this.progress=0;this.spawn=1.5}
 update(dt){this.life-=dt;if(this.kind==="rift"&&!this.used){const inside=Math.hypot(game.player.x-this.x,game.player.y-this.y)<110;if(inside)this.progress+=dt;else this.progress=Math.max(0,this.progress-dt*.35);this.spawn-=dt;if(this.spawn<=0){this.spawn=2.1;for(let i=0;i<2;i++){const a=Math.random()*Math.PI*2,r=145;game.enemies.push(vsxApplyDifficulty(new Enemy(Math.random()<.5?"runner":"swarmer",this.x+Math.cos(a)*r,this.y+Math.sin(a)*r,game.difficulty)))}}if(this.progress>=4){this.used=true;this.dead=true;if(game.worldEvent?.id==="rift_breach"){game.worldEvent.closed=(game.worldEvent.closed||0)+1;game.player.heal(game.player.maxHp*.05);VSX.announce(WORLD_EVENT_DEFINITIONS.rift_breach.name[VSX.lang],`${game.worldEvent.closed}/3`,"#a986ff")}}}if(this.life<=0)this.dead=true}
 interact(){if(this.kind==="mountain"&&!this.used&&game.worldEvent?.id==="mountain_protocol"){this.used=true;game.worldEvent.active=true;game.worldEvent.time=35;game.worldEvent.max=35;game.worldEvent.mountainKills=0;VSX.announce(WORLD_EVENT_DEFINITIONS.mountain_protocol.name[VSX.lang],VSX.lang==="vi"?"THỬ THÁCH ĐÃ CHẤP NHẬN":"CHALLENGE ACCEPTED","#ffd06b")}}
 render(g){g.save();g.translate(this.x,this.y);const c=this.kind==="mountain"?"#ffd06b":"#9a79ff";g.shadowBlur=16;g.shadowColor=c;g.strokeStyle=c;g.lineWidth=3;g.beginPath();g.arc(0,0,this.kind==="mountain"?23:28,0,Math.PI*2);g.stroke();if(this.kind==="rift"){g.globalAlpha=.18;g.fillStyle=c;g.beginPath();g.arc(0,0,80,0,Math.PI*2);g.fill();g.globalAlpha=1;g.strokeStyle="#d7c7ff";g.beginPath();g.arc(0,0,34,-Math.PI/2,-Math.PI/2+Math.PI*2*clamp(this.progress/4,0,1));g.stroke()}else{const pulse=.5+.5*Math.sin((game.time||0)*5);g.globalAlpha=.12+.08*pulse;g.fillStyle=c;g.beginPath();g.arc(0,0,64+6*pulse,0,Math.PI*2);g.fill();g.globalAlpha=.65;g.strokeStyle=c;g.setLineDash([7,7]);g.beginPath();g.arc(0,0,48+5*pulse,0,Math.PI*2);g.stroke();g.setLineDash([]);g.globalAlpha=.32;g.fillStyle=c;g.fillRect(-4,-120,8,92);g.globalAlpha=1;g.fillStyle=c;g.beginPath();g.moveTo(0,-18);g.lineTo(15,13);g.lineTo(-15,13);g.closePath();g.fill();g.fillStyle="#fff4bd";g.font="900 10px Arial";g.textAlign="center";g.fillText("E",0,4)}g.restore()}
}
class VSX_GravityCore{
 constructor(x,y){this.x=x;this.y=y;this.life=this.max=5;this.dead=false;this.radius=170}
 update(dt){this.life-=dt;const p=game.player,dp=Math.hypot(this.x-p.x,this.y-p.y);if(dp<this.radius){const n=normalize(this.x-p.x,this.y-p.y);p.x+=n.x*58*dt;p.y+=n.y*58*dt}for(const e of game.grid.queryCircle(this.x,this.y,this.radius)){if(e.dead)continue;const d=Math.hypot(this.x-e.x,this.y-e.y);if(d<this.radius){const n=normalize(this.x-e.x,this.y-e.y);e.x+=n.x*95*dt*(1-(e.knockbackResistance||0));e.y+=n.y*95*dt*(1-(e.knockbackResistance||0))}}for(const q of game.projectiles){if(q.dead)continue;const d=Math.hypot(this.x-q.x,this.y-q.y);if(d<this.radius){const n=normalize(this.x-q.x,this.y-q.y);q.vx+=n.x*115*dt;q.vy+=n.y*115*dt}}if(this.life<=0){game.explosion(this.x,this.y,78,58,"#986cff",80,{id:"gravity_storm",def:{tags:["world_event","area"]}},false);if(Math.hypot(p.x-this.x,p.y-this.y)<78+p.radius)p.takeDamage(12,{worldEvent:true});this.dead=true}}
 render(g){const t=clamp(this.life/this.max,0,1);g.save();g.fillStyle="rgba(134,92,255,.12)";g.strokeStyle="#9f7cff";g.lineWidth=2;g.beginPath();g.arc(this.x,this.y,this.radius,0,Math.PI*2);g.fill();g.stroke();g.fillStyle="#d7c5ff";g.beginPath();g.arc(this.x,this.y,9+8*(1-t),0,Math.PI*2);g.fill();g.restore()}
}
function vsxInitExpandedEvent(g,id){g.vsxEventObjects||=[];if(id==="infernal_cache"){g.worldEvent.startKills=g.kills;g.worldEvent.goal=40;const a=Math.random()*Math.PI*2,r=260;const m=new VSX_EventBeacon("cache",g.player.x+Math.cos(a)*r,g.player.y+Math.sin(a)*r);m.type="generator";g.vsxEventObjects.push(m);vsxMapEventObject(g,m,"generator")}else if(id==="mountain_protocol"){const a=Math.random()*Math.PI*2,r=175,b=new VSX_EventBeacon("mountain",g.player.x+Math.cos(a)*r,g.player.y+Math.sin(a)*r);g.vsxEventObjects.push(b);vsxMapEventObject(g,b,"shrine");g.nearExpandedEventInteractable=null}else if(id==="gravity_storm"){g.worldEvent.coreTimer=.7}else if(id==="kill_chain"){Object.assign(g.worldEvent,{chain:0,best:0,chainTimer:0,tier20:false,tier40:false,tier60:false})}else if(id==="rift_breach"){g.worldEvent.closed=0;for(let i=0;i<3;i++){const a=i*Math.PI*2/3+Math.random()*.4,r=rand(360,210);{const q=new VSX_EventBeacon("rift",g.player.x+Math.cos(a)*r,g.player.y+Math.sin(a)*r);g.vsxEventObjects.push(q);vsxMapEventObject(g,q,"trial_portal")}}}else if(id==="bullet_bank"){g.vsxBankedBullets=[]}}
function vsxUpdateExpandedEvent(g,dt){const ev=g.worldEvent;if(!ev)return;const id=ev.id;if(id==="infernal_cache"){if(g.kills-(ev.startKills||0)>=ev.goal){g.chests.push(new Chest(g.player.x+45,g.player.y));g.pickups.push(new Pickup(g.player.x-35,g.player.y,"golden_boost"));g.player.gainXP(65);ev.completed=true;ev.time=0}else if(g.eventSpawnTimer<=0){g.eventSpawnTimer=1.2;for(let i=0;i<3;i++)g.spawnManager.spawnOne(i===0&&Math.random()<.3)}}
 else if(id==="mountain_protocol"){const beacon=g.vsxEventObjects?.find(o=>o.kind==="mountain"&&!o.dead);g.nearExpandedEventInteractable=beacon&&Math.hypot(beacon.x-g.player.x,beacon.y-g.player.y)<75?beacon:null;if(ev.active&&g.eventSpawnTimer<=0){g.eventSpawnTimer=.75;g.spawnManager.spawnOne(Math.random()<.42)}}
 else if(id==="gravity_storm"){ev.coreTimer=(ev.coreTimer||0)-dt;if(ev.coreTimer<=0){ev.coreTimer=6;const a=Math.random()*Math.PI*2,r=rand(260,100);g.vsxEventObjects.push(new VSX_GravityCore(g.player.x+Math.cos(a)*r,g.player.y+Math.sin(a)*r))}}
 else if(id==="kill_chain"){if(ev.chainTimer>0){ev.chainTimer-=dt;if(ev.chainTimer<=0)ev.chain=0}}
 else if(id==="rift_breach"){if((ev.closed||0)>=3&&!ev.completed){ev.completed=true;g.chests.push(new Chest(g.player.x+40,g.player.y));g.pickups.push(new Pickup(g.player.x-35,g.player.y,"golden_boost"));g.player.gainXP(80);ev.time=0}}
 else if(id==="bullet_bank"){g.vsxBankedBullets||=[];for(const p of g.enemyProjectiles){if(p.dead||g.vsxBankedBullets.length>=70)continue;const d=Math.hypot(p.x-g.player.x,p.y-g.player.y);if(d<270&&d>80){g.vsxBankedBullets.push({x:p.x,y:p.y,vx:p.vx,vy:p.vy,damage:p.damage,color:p.color||"#ff7a9a",radius:p.radius||5,dead:false});p.dead=true}}}
 for(const o of g.vsxEventObjects||[])if(!o.dead)o.update(dt);g.vsxEventObjects=(g.vsxEventObjects||[]).filter(o=>!o.dead)}
function vsxFinishExpandedEvent(g,prev){const id=prev.id;if(id==="infernal_cache"&&!prev.completed){const k=g.kills-(prev.startKills||0);if(k>=20){g.chests.push(new Chest(g.player.x+35,g.player.y));g.player.gainXP(35)}}else if(id==="mountain_protocol"&&prev.active){g.chests.push(new Chest(g.player.x+38,g.player.y));g.pickups.push(new Pickup(g.player.x-32,g.player.y,"golden_boost"))}else if(id==="bullet_bank"){let released=0;for(const b of g.vsxBankedBullets||[]){if(b.dead)continue;const n=normalize(g.player.x-b.x,g.player.y-b.y),sp=Math.max(180,Math.hypot(b.vx,b.vy));g.enemyProjectiles.push(new Projectile({x:b.x,y:b.y,vx:n.x*sp,vy:n.y*sp,radius:b.radius,damage:b.damage,life:3,color:b.color,owner:"enemy",critAllowed:false}));if(++released>=55)break}g.vsxBankedBullets=[]}for(const o of g.vsxEventObjects||[])o.dead=true;g.vsxEventObjects=[];g.nearExpandedEventInteractable=null}

const MU_INIT_BASE=Game.prototype.vsxInitRun;
Game.prototype.vsxInitRun=function(){MU_INIT_BASE.call(this);this.vsxCoins=[];this.vsxPrisms=[];this.vsxHourglassMines=[];this.vsxEventObjects=[];this.vsxBankedBullets=[];this.nearExpandedEventInteractable=null};
const MU_EVENT_START_BASE=Game.prototype.startWorldEvent;
Game.prototype.startWorldEvent=function(){const before=this.worldEvent;const r=MU_EVENT_START_BASE.call(this);if(!before&&this.worldEvent&&["infernal_cache","mountain_protocol","gravity_storm","kill_chain","rift_breach","bullet_bank"].includes(this.worldEvent.id))vsxInitExpandedEvent(this,this.worldEvent.id);return r};
const MU_GAME_UPDATE_BASE=Game.prototype.update;
Game.prototype.update=function(dt){
 const speed=VSX_ADMIN?.speed||1,scaled=dt*speed,oldTime=this.time;
 if(this.state==="PLAYING"&&this.worldEvent){try{vsxUpdateExpandedEvent(this,scaled);if(this.worldEvent)this.worldEvent._vsxExpandedFaults=0}catch(err){const ev=this.worldEvent;if(ev)ev._vsxExpandedFaults=(ev._vsxExpandedFaults||0)+1;console.error("[EXPANDED WORLD EVENT UPDATE]",ev?.id,`fault ${ev?._vsxExpandedFaults||1}/3`,err);try{window.VSX_RUNTIME_SAFETY?.state?.log?.push?.({ts:Date.now(),level:(ev?._vsxExpandedFaults||1)>=3?"ERROR":"WARN",code:(ev?._vsxExpandedFaults||1)>=3?"WORLD_EXPANDED_FATAL":"WORLD_EXPANDED_RETRY",character:this.characterId||"unknown",detail:String(err?.stack||err)})}catch{}if((ev?._vsxExpandedFaults||1)>=3){if(typeof abortWorldEvent==="function")abortWorldEvent("expanded-event-runtime",err);else throw err}}}
 const eventSnap=this.worldEvent?{...this.worldEvent}:null;
 const r=MU_GAME_UPDATE_BASE.call(this,scaled);
 if(this.state==="PLAYING")vsxUpdatePuppets(this,scaled);
 if(eventSnap&&!this.worldEvent)vsxFinishExpandedEvent(this,eventSnap);
 if(VSX_ADMIN?.freezeTime&&this.state==="PLAYING"){this.time=oldTime;this.wave=1+Math.floor(this.time/60)}
 if(VSX_ADMIN?.noCooldown&&this.player){this.dashCooldown=0;this.ultimateCharge=100}
 if(VSX_ADMIN?.infiniteRerolls){this.rerollsRemaining=Math.max(this.rerollsRemaining||0,999);this.rerollsMax=Math.max(this.rerollsMax||0,999)}
 return r
};
const MU_GAME_RENDER_BASE=Game.prototype.render;
Game.prototype.render=function(){MU_GAME_RENDER_BASE.call(this);if(!this.player||this.state==="TITLE")return;ctx.save();ctx.translate(-this.camera.x,-this.camera.y);for(const o of this.vsxEventObjects||[])if(!o.dead)o.render(ctx);if(this.worldEvent?.id==="bullet_bank"){for(const b of this.vsxBankedBullets||[]){if(b.dead)continue;ctx.shadowBlur=8;ctx.shadowColor=b.color;ctx.fillStyle=b.color;ctx.beginPath();ctx.arc(b.x,b.y,b.radius,0,Math.PI*2);ctx.fill()}ctx.shadowBlur=0}ctx.restore()};

const MU_ENEMY_DIE_BASE=Enemy.prototype.die;
Enemy.prototype.die=function(drop=true){if(this.dead)return;MU_ENEMY_DIE_BASE.call(this,drop);const ev=game.worldEvent;if(ev?.id==="kill_chain"){ev.chain=(ev.chain||0)+1;ev.best=Math.max(ev.best||0,ev.chain);ev.chainTimer=2.5;if(ev.chain>=20&&!ev.tier20){ev.tier20=true;game.player.gainXP(35);VSX.announce(WORLD_EVENT_DEFINITIONS.kill_chain.name[VSX.lang],"20 CHAIN • XP","#8ff0bd")}if(ev.chain>=40&&!ev.tier40){ev.tier40=true;game.chests.push(new Chest(game.player.x+30,game.player.y));VSX.announce(WORLD_EVENT_DEFINITIONS.kill_chain.name[VSX.lang],"40 CHAIN • CHEST","#ffd06b")}if(ev.chain>=60&&!ev.tier60){ev.tier60=true;game.pickups.push(new Pickup(game.player.x-30,game.player.y,"golden_boost"));VSX.announce(WORLD_EVENT_DEFINITIONS.kill_chain.name[VSX.lang],"60 CHAIN • GOLDEN BOOST","#ffd84d")}}};

// Extra spawn pressure for accepted Mountain Protocol.
const MU_SPAWN_BASE=SpawnManager.prototype.update;
SpawnManager.prototype.update=function(dt){if(VSX_ADMIN?.freezeSpawns)return;return MU_SPAWN_BASE.call(this,dt)};

// E interaction for Mountain Protocol.
const MU_HANDLE_BASE=Game.prototype.handleKey;
Game.prototype.handleKey=function(code){if(this.state==="PLAYING"&&code==="KeyE"&&this.nearExpandedEventInteractable){this.nearExpandedEventInteractable.interact();return}return MU_HANDLE_BASE.call(this,code)};

// ---------- ADMIN CONTROL ----------
const VSX_ADMIN=window.VSX_ADMIN={enabled:false,open:false,tab:"run",previousState:"TITLE",speed:1,freezeTime:false,freezeSpawns:false,invincible:false,oneHit:false,noCooldown:false,infiniteRerolls:false,infScore:false,infKills:false,backup:null,weaponMissingOnly:false,adminMoveSpeed:1,adminAttackSpeed:1,adminProjectileSpeed:1};
const ADMIN_TABS=["run","player","loadout","spawn","boss","allies","meta","collection","debug"];
function adminL(en,vi){return VSX.lang==="vi"?vi:en}
function adminToggleRow(label,key){return `<label class="vsxAdminToggle"><span>${label}</span><input type="checkbox" data-admin-toggle="${key}" ${VSX_ADMIN[key]?"checked":""}></label>`}
function adminCard(title,body,cls=""){return `<div class="vsxAdminCard ${cls}"><h3>${title}</h3>${body}</div>`}
function adminButton(id,label){return `<button data-admin-action="${id}">${label}</button>`}
function adminSelect(id,entries){return `<select id="${id}">${entries.map(([v,l])=>`<option value="${VSX.esc(String(v))}">${VSX.esc(String(l))}</option>`).join("")}</select>`}
function adminOpen(tab=VSX_ADMIN.tab){if(!VSX_ADMIN.enabled)return;if(!["TITLE","PLAYING","PAUSED","ADMIN"].includes(game.state))return;VSX_ADMIN.tab=tab;const s=document.getElementById("vsxAdminScreen");if(!s)return;if(!VSX_ADMIN.open){VSX_ADMIN.previousState=game.state;VSX_ADMIN.open=true;if(game.state==="PLAYING"||game.state==="PAUSED")game.state="ADMIN"}s.classList.add("active");titleScreen.classList.remove("active");renderAdmin()}
function adminClose(){const s=document.getElementById("vsxAdminScreen");if(!s)return;s.classList.remove("active");if(!VSX_ADMIN.open)return;VSX_ADMIN.open=false;if(VSX_ADMIN.previousState==="TITLE"){game.state="TITLE";titleScreen.classList.add("active")}else if(VSX_ADMIN.previousState==="PAUSED"){game.state="PAUSED";pauseScreen.classList.add("active")}else if(game.player){game.state="PLAYING";hud.classList.add("active")}}
function adminSetEnabled(v){VSX_ADMIN.enabled=!!v;document.body.classList.toggle("vsxDevMode",VSX_ADMIN.enabled);if(!v&&VSX_ADMIN.open)adminClose();VSX.announce("DEV MODE",VSX_ADMIN.enabled?adminL("ENABLED","ĐÃ BẬT"):adminL("DISABLED","ĐÃ TẮT"),VSX_ADMIN.enabled?"#73f5bd":"#ff8d98")}
function ensureAdminCollectionSave(){ensureArmorySave();VSX.save.meta.adminOwnedWeapons||={};for(const c of ["weapons","passives","allies","evolutions","mutations","synergies","enemies","bosses","characters","achievements","legendary_relics","trials"])VSX.save.codex[c]||={}}
function adminWeaponOwned(id){const d=WEAPON_DEFINITIONS[id];if(!d)return false;ensureAdminCollectionSave();if(VSX.save.meta.adminOwnedWeapons[id])return true;if(d.rewardOnly)return false;return isWeaponUnlocked(id)}
function adminOwnWeapon(id,announce=true){const d=WEAPON_DEFINITIONS[id];if(!d)return false;ensureAdminCollectionSave();VSX.save.meta.adminOwnedWeapons[id]=true;VSX.save.meta.unlockedWeapons[id]=true;VSX.save.codex.weapons[id]=true;if(d.legendaryRelic)VSX.save.codex.legendary_relics[id]=true;vsxSave();if(announce)VSX.announce("ADMIN",`${adminL("WEAPON OWNED","ĐÃ SỞ HỮU VŨ KHÍ")}: ${weaponName(id)}`,d.rewardOnly?"#ffd86a":"#73f5bd");return true}
function adminOwnAllWeapons(){ensureAdminCollectionSave();for(const id of Object.keys(WEAPON_DEFINITIONS))adminOwnWeapon(id,false);vsxSave();VSX.announce("ADMIN",adminL("ALL WEAPONS OWNED","ĐÃ SỞ HỮU TOÀN BỘ VŨ KHÍ"),"#73f5bd")}
function adminRevealFullCollection(){ensureAdminCollectionSave();for(const cat of ["weapons","passives","allies","evolutions","mutations","synergies","enemies","bosses","characters","achievements","legendary_relics","trials"]){const entries=VSX.codexEntries?.(cat)||[];VSX.save.codex[cat]||={};for(const row of entries)if(row?.[0])VSX.save.codex[cat][row[0]]=true}vsxSave()}
function adminUnlockFull(){ensureAdminCollectionSave();for(const id of Object.keys(WEAPON_DEFINITIONS)){VSX.save.meta.unlockedWeapons[id]=true;VSX.save.meta.adminOwnedWeapons[id]=true}for(const id of Object.keys(PASSIVE_DEFINITIONS))VSX.save.meta.unlockedPassives[id]=true;for(const id of Object.keys(CHARACTER_DEFINITIONS))VSX.save.meta.unlockedCharacters[id]=true;for(const id of Object.keys(CONTRACT_DEFINITIONS))VSX.save.meta.contractLicenses[id]=true;for(const id of Object.keys(SKIN_DEFINITIONS))VSX.save.meta.skins[id]=true;adminRevealFullCollection();vsxSave();VSX.announce("ADMIN",adminL("FULL GAME + COLLECTION UNLOCKED","ĐÃ MỞ KHÓA TOÀN BỘ GAME + COLLECTION"),"#ffd86a")}
function adminWeaponStatusChips(id){const d=WEAPON_DEFINITIONS[id],owned=adminWeaponOwned(id),drop=!d.rewardOnly&&normalWeaponPool().includes(id);return `<span class="vsxAdmChip ${owned?"ok":"dim"}">${owned?adminL("OWNED","SỞ HỮU"):adminL("NOT OWNED","CHƯA SỞ HỮU")}</span>${drop?`<span class="vsxAdmChip">${adminL("DROP POOL","POOL RƠI")}</span>`:""}${d.rewardOnly?`<span class="vsxAdmChip gold">${adminL("REWARD ONLY","CHỈ PHẦN THƯỞNG")}</span>`:""}${d.legendaryRelic?`<span class="vsxAdmChip gold">${adminL("RELIC","DI VẬT")}</span>`:""}`}
function renderAdminWeaponCards(){const grid=document.getElementById("admWeaponManagerGrid");if(!grid)return;ensureAdminCollectionSave();const q=(document.getElementById("admWeaponSearch")?.value||"").trim().toLowerCase(),rar=document.getElementById("admWeaponRarity")?.value||"all",all=Object.keys(WEAPON_DEFINITIONS);const items=all.filter(id=>{const d=WEAPON_DEFINITIONS[id],name=weaponName(id).toLowerCase();if(q&&!name.includes(q)&&!id.toLowerCase().includes(q))return false;if(rar!=="all"&&(d.rarity||"common")!==rar)return false;if(VSX_ADMIN.weaponMissingOnly&&adminWeaponOwned(id))return false;return true});grid.innerHTML=items.map(id=>{const d=WEAPON_DEFINITIONS[id],owned=adminWeaponOwned(id),seen=!!VSX.save.codex.weapons?.[id],inRun=!!game.player?.weapons?.some(w=>w.id===id),canGrant=!!game.player&&!inRun&&game.player.weapons.length<game.player.weaponSlots;return `<div class="vsxAdminWeaponItem ${owned?"vsxAdmOwned":""} ${d.rewardOnly?"vsxAdmReward":""}"><div class="vsxAdmWeaponHead"><b>${VSX.esc(weaponName(id))}</b><span class="vsxAdmRarity">${VSX.esc((d.rarity||"common").toUpperCase())}</span></div><div class="vsxAdmWeaponDesc">${VSX.esc(weaponDesc(id))}</div><div class="vsxAdmWeaponTags">${adminWeaponStatusChips(id)}</div><div class="vsxAdmWeaponActions"><button data-admin-own-weapon="${id}">${owned&&seen?adminL("OWNED","ĐÃ SỞ HỮU"):adminL("OWN","SỞ HỮU")}</button><button data-admin-run-weapon="${id}" ${inRun||!canGrant?"disabled":""}>${inRun?adminL("IN RUN","ĐANG DÙNG"):adminL("GRANT TO RUN","ADD VÀO TRẬN")}</button></div></div>`}).join("")||`<p>${adminL("No weapons match this filter.","Không có vũ khí phù hợp bộ lọc.")}</p>`;document.querySelectorAll("[data-admin-own-weapon]").forEach(b=>b.onclick=()=>{adminOwnWeapon(b.dataset.adminOwnWeapon);renderAdminWeaponCards()});document.querySelectorAll("[data-admin-run-weapon]").forEach(b=>b.onclick=()=>{const id=b.dataset.adminRunWeapon;if(!game.player)return;if(game.player.weapons.some(w=>w.id===id))return;if(game.player.weapons.length>=game.player.weaponSlots){VSX.announce("ADMIN",adminL("NO FREE WEAPON SLOT","KHÔNG CÒN Ô VŨ KHÍ"),"#ff8d98");return}adminOwnWeapon(id,false);game.player.addWeapon(id);VSX.announce("ADMIN",`${adminL("GRANTED TO RUN","ĐÃ ADD VÀO TRẬN")}: ${weaponName(id)}`,"#73f5bd");renderAdminWeaponCards()})}
function adminForceEvent(id){if(!game.player)return;for(const o of game.vsxEventObjects||[])o.dead=true;game.worldEvent=null;game.vsxEventObjects=[];const d=WORLD_EVENT_DEFINITIONS[id];game.worldEvent={id,time:d.duration,max:d.duration};game.lastMajorEncounterTime=game.time;game.eventTick=0;game.eventSpawnTimer=0;if(["infernal_cache","mountain_protocol","gravity_storm","kill_chain","rift_breach","bullet_bank"].includes(id))vsxInitExpandedEvent(game,id);VSX.announce(t("worldEvent"),d.name[VSX.lang],"#ffb05d")}
function adminSpawnBoss(wave){if(!game.player)return;if(game.boss&&!game.boss.dead)game.boss.dead=true;game.boss=null;game.pendingBigBossWave=null;game.worldEvent=null;game.miniBoss=null;game.spawnBigBossForWave(Number(wave)||5)}
function adminRecruit(id){if(!game.player)return;if(game.storyAllyMap?.has(id)){const a=game.storyAllyMap.get(id);a.dead=false;a.hp=a.maxHp;return}game.recruitAlly(id,game.player.x+rand(55,-55),game.player.y+rand(55,-55))}
